-- =============================================================
-- 导入后处理（跨环境适配）
-- =============================================================

-- 1) 找到目标库的「数据库存储」配置（storage = 1）
SET @file_config_id := (
    SELECT `id` FROM `infra_file_config`
    WHERE `storage` = 1 AND `deleted` = b'0'
    ORDER BY `id` LIMIT 1
);
SELECT IF(@file_config_id IS NULL,
          '⚠ 目标库没有「数据库存储」文件配置，请先在「基础设施 → 文件配置」新建一条数据库存储配置，再重新执行本脚本',
          CONCAT('使用文件配置 id = ', @file_config_id)) AS hint;

-- 2) 把 URL 中的配置号改写成目标库的配置号（URL 形如 /admin-api/infra/file/4/get/xxx）
UPDATE `infra_file`
SET `url` = REGEXP_REPLACE(`url`, '/admin-api/infra/file/[0-9]+/',
                           CONCAT('/admin-api/infra/file/', @file_config_id, '/'))
WHERE @file_config_id IS NOT NULL
  AND (`path` LIKE 'hrm/template/%' OR `path` LIKE '%labor-contract-template.docx%');

UPDATE `hrm_contract_template`
SET `file_url` = REGEXP_REPLACE(`file_url`, '/admin-api/infra/file/[0-9]+/',
                                CONCAT('/admin-api/infra/file/', @file_config_id, '/')),
    `thumbnail_url` = REGEXP_REPLACE(`thumbnail_url`, '/admin-api/infra/file/[0-9]+/',
                                     CONCAT('/admin-api/infra/file/', @file_config_id, '/')),
    `preview_url` = REGEXP_REPLACE(`preview_url`, '/admin-api/infra/file/[0-9]+/',
                                   CONCAT('/admin-api/infra/file/', @file_config_id, '/'))
WHERE `deleted` = b'0' AND @file_config_id IS NOT NULL;

-- 3) 把导入的文件记录挂到目标库的配置上
UPDATE `infra_file` SET `config_id` = @file_config_id
WHERE @file_config_id IS NOT NULL
  AND (`path` LIKE 'hrm/template/%' OR `path` LIKE '%labor-contract-template.docx%');

UPDATE `infra_file_content` SET `config_id` = @file_config_id
WHERE @file_config_id IS NOT NULL
  AND (`path` LIKE 'hrm/template/%' OR `path` LIKE '%labor-contract-template.docx%');

-- 4) 落到目标租户
UPDATE `hrm_contract_template` SET `tenant_id` = @target_tenant_id WHERE `deleted` = b'0';

-- 5) 校验：模板数 / 模板文件元数据 / 模板文件字节
SELECT '模板数' AS item, COUNT(*) AS cnt FROM `hrm_contract_template` WHERE `deleted` = b'0'
UNION ALL SELECT '模板文件(元数据)', COUNT(*) FROM `infra_file`
    WHERE `path` LIKE 'hrm/template/%' OR `path` LIKE '%labor-contract-template.docx%'
UNION ALL SELECT '模板文件(字节)', COUNT(*) FROM `infra_file_content`
    WHERE `path` LIKE 'hrm/template/%' OR `path` LIKE '%labor-contract-template.docx%';
